  /* Run after DOM is ready */
  function init() {
    var img    = document.getElementById('irr-product-img');
    var tabs   = document.querySelectorAll('.irr-prod-tab');
    var panels = document.querySelectorAll('.irr-panel');

    if (!img || !tabs.length) return;

    /* Swap product image with fade */
    function setImage(panelId) {
      var src = imageMap[panelId];
      if (!src || src.indexOf('YOUR-SITE') !== -1) return;
      img.style.opacity = '0';
      setTimeout(function () {
        img.src = src;
        img.alt = panelId;
        img.style.opacity = '1';
      }, 180);
    }

    /* Activate a content panel */
    function activatePanel(panelId) {
      panels.forEach(function (p) { p.classList.remove('active'); });
      var target = document.getElementById('panel-' + panelId);
      if (target) {
        target.classList.add('active');
        setImage(panelId);
      }
    }

    /* Tab click */
    tabs.forEach(function (btn) {
      btn.addEventListener('click', function () {
        tabs.forEach(function (b) { b.classList.remove('active'); });
        btn.classList.add('active');
        activatePanel(btn.dataset.panel);
      });
    });

    /* Init: load first image */
    activatePanel('irr-standard');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
