/* ── Left: image container ──────────────────────────── */
.irr-image-col {
  flex: 0 0 42%;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 30px;
  min-height: 420px;
  border-radius: 12px;
  box-shadow: 0px 20px 40px 0px #0F1D280F;
  box-sizing: border-box;
