.irr-image-col img {
  width: 100%;
  max-width: 340px;
  height: auto;
  object-fit: contain;
  transition: opacity 0.35s ease;
  display: block;
}

/* ── Right: tabs column ─────────────────────────────── */
.irr-tabs-col {
  flex: 1 1 58%;
  padding: 24px 48px 24px 40px;
