  flex-direction: column;
  gap: 0;
  box-sizing: border-box;
}

/* ── Product tabs: Standard / Tall / Tall XL ──────── */
.irr-prod-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}

.irr-prod-tab {
  font-family: 'Inter', sans-serif;
  background: #FFFFFF;
  border: 1.5px solid rgba(0, 82, 135, 0.2);
  border-radius: 6px;
  outline: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: #333333;
  padding: 8px 20px;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
  letter-spacing: 0.01em;
}

.irr-prod-tab:hover {
  border-color: #005287;
  color: #FFF;
  background-color: #005287 !important;
}

.irr-prod-tab.active {
  background: #005287;
  border-color: #005287;
  color: #FFFFFF;
}

/* ── Content panels ─────────────────────────────────── */
.irr-panel {
  display: none;
  flex-direction: column;
  gap: 6px;
  animation: irrFadeIn 0.25s ease;
}

.irr-panel.active { display: flex; }

@keyframes irrFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Product title */
.irr-product-name {
